    "primaryMantra": {
      "sanskrit": "एक॑ ए॒वाग्निर्ब॑हु॒धा समि॑द्ध॒ एकः॒ सूर्यो॒ विश्व॒मनु॒ प्रभू॑तः।\nएकै॒वोषाः सर्व॑मि॒दं वि भा॑त्येकं॒ वा इ॒दं वि ब॑भूव॒ सर्व॑म्॥\n\nतमिन्द्रं॑ वाजयामसि म॒हे वृ॒त्राय॒ हन्त॑वे।\nस वृ॑षा वृष॒भो भु॑वत्॥",
      "ref": "ऋग्वेद ८.५८.२ (अद्वैत ब्रह्म महावाक्य) एवं ८.६.१ (इंद्र महास्तुति)",
      "translation": "अग्नि तत्व एक ही है जो अनेक रूपों में प्रज्वलित होता है; सूर्य एक ही है जो संपूर्ण ब्रह्मांड में व्याप्त होकर प्रकाशित होता है; उषा एक ही है जो इस समस्त जगत को आलोकित करती है; और वास्तव में यह संपूर्ण विश्व उसी एक परब्रह्म की ही विविध अभिव्यक्ति है! हम महान अज्ञानरूपी वृत्र के नाश हेतु उस समर्थ इंद्र की स्तुति करते हैं; वह परम पराक्रमी प्रभु हमें समस्त आध्यात्मिक ऐश्वर्य प्रदान करें।"
    },
