      "anuvaka": "वर्णोच्चारण, स्वर-मीमांसा, संधि-विधान, छन्दोलक्षण, पाठ-विकृतियाँ",
      "rishi": "महर्षि शौनक",
      "devata": "सरस्वती, वाक्, ब्रह्म",
