    "traditionsDifferences": "ऋग्वेद में यह प्रथम सूक्त है। सामवेद में यह 'अग्न आ याहि वीतये' (सामवेद १.१) से प्रारंभ होता है। शुक्ल यजुर्वेद 'इषे त्वोर्जे त्वा' (यजुर्वेद १.१) से और अथर्ववेद 'ये त्रिषप्ताः' (अथर्ववेद १.१) से प्रारंभ होता है।",
    "historyResearch": "आचार्य यास्क ने निरुक्त (७.१४) में अग्नि शब्द का निर्वचन 'अग्रणीर्भवति' (जो सबसे आगे ले जाता है) किया है। महर्षि दयानंद सरस्वती ने सत्यार्थ प्रकाश में अग्नि को ईश्वर का प्रथम वाचक नाम सिद्ध किया। आधुनिक खगोलभौतिकी में अग्नि को 'कॉस्मिक एनर्जी' (Cosmic Energy/Plasma) के प्राचीनतम स्वरूप के रूप में देखा गया है।",
