      "sanskrit": "ॐ स॒हस्र॑शीर्षा॒ पुरु॑षः सहस्रा॒क्षः स॒हस्र॑पात्।\nस भूमिं॑ वि॒श्वतो॑ वृ॒त्वात्य॑तिष्ठद्दशाङ्गु॒लम्॥१॥\n\nपुरु॑ष ए॒वेदं सर्वं॒ यद्भू॒तं यच्च॒ भव्य॑म्।\nउ॒तामृ॑त॒त्वस्येशानो॒ यदन्ने॑नाति॒रोह॑ति॥२॥",
